window.AUTH=window.AUTH||{};window.AUTH["06-562"]={"d":"06-562","id":"2006/06-562","n":"United States v. Atlantic Research Corp.","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/213096/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-atlantic-research-corp-brief-merits","n":108}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep551/usrep551128/usrep551128.pdf","tr":true,"items":[{"t":"case","label":"AT&T Co. v. Central Office Tel., Inc.","cite":"524 U.S. 214","y":1998,"id":"1997/97-679","sc":1,"sum":"The Court held that Communications Act's filed-tariff requirements pre-empt Central Office Telephone, Inc.'s state-law claims.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Akzo Coatings, Inc. v. Aigner Corp.","cite":"30 F.3d 761","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/30/761/","by":{"0":"6, 16, 31, 38"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"17, 22"}},{"t":"case","label":"Amcast Indus. Corp. v. Detrex Corp.","cite":"2 F.3d 746","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/2/746/","by":{"0":"38"}},{"t":"case","label":"Atherton v. FDIC","cite":"519 U.S. 213","y":1997,"id":"1996/95-928","sc":1,"sum":"The unanimous Court concluded that \"state law sets the standard of conduct as long as the state standard is stricter than that of the federal statute.\" The opinion by Justice Stephen Breyer held that the federal \"gross negligence\" statute was only intended to set a \"floor\" or minimum standard for state laws governing negligent conduct.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Bedford Affiliates v. Sills","cite":"156 F.3d 416","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/156/416/","sum":"Reasoning that, if a PRP could sue under Section 107(a), “[a] recovering liable party would readily abandon a § 113(f)(1) suit in favor of the substantially more generous provisions of § 107(a)”.","sumSrc":"brief:0","by":{"0":"6, 30"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bu- reau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Block v. North Dakota","cite":"461 U.S. 273","y":1983,"id":"1982/81-2337","sc":1,"sum":"North Dakota filed suit in Federal District Court against several federal officials to resolve a dispute as to ownership of certain portions of a riverbed within the State. The United States claims title to most of the disputed area on the basis of its status as a riparian landowner on a nonnavigable river, while the State asserts that the river was navigable when North Dakota was admitted to the Union in 1889 and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 31"}},{"t":"case","label":"Brown v. GSA","cite":"425 U.S. 820","y":1976,"id":"1975/74-768","sc":1,"sum":"Section 717 provides the exBROWN v. GSA","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Busic v. United States","cite":"446 U.S. 398","y":1980,"id":"1979/78-6020","sc":1,"sum":"Section 924 (c) may not be applied to a defendant who uses a firearm in the course of a felony that is proscribed by a statute which itself authorizes enhancement if a dangerous weapon is used. The sentence received by such a defendant may be enhanced only under the enhancement provision in the statute defining the felony he committed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Carson Harbor Village Ltd. v. County of Los Angeles","cite":"433 F.3d 1260","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/433/1260/","by":{"0":"20"}},{"t":"case","label":"Centerior Service Co. v. Acme Scrap Iron & Metal Corp.","cite":"153 F.3d 344","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/153/344/","by":{"0":"6, 31, 33"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"op":1,"sum":"Stating in dictum that § 107 “impliedly authorizes private parties to recover cleanup costs from other PRP[s]” (empha­ sis added).","sumSrc":"opinion","by":{"0":"17"}},{"t":"case","label":"City of New York v. Exxon Corp.","cite":"633 F. Supp. 609","y":1986,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./633/609/","by":{"0":"28"}},{"t":"case","label":"City of Philadelphia v. Stepan Chem. Co.","cite":"544 F. Supp. 1135","y":1982,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./544/1135/","sum":"Holding that PRP had right to cost recovery under Section 107(a)(1)-(4)(B).","sumSrc":"brief:0","by":{"0":"5, 28"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"sum":"The Court held that Abrams could not enforce the limitations of the Telecommunications Act on local authorities through federal liability law, because the act provides its own judicial remedy. Congress could not have meant the judicial remedy expressly authorized by the Telecommunications Act to co-exist with an alternative remedy.","sumSrc":"Oyez","by":{"0":"27, 31"}},{"t":"case","label":"Coeur d’Alene Tribe v. Asarco Inc.","cite":"280 F. Supp. 2d 1094","y":2003,"court":"D. Idaho","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/280/1094/","by":{"0":"44"}},{"t":"case","label":"Consolidated Edison Co. of New York, Inc. v. UGI Utils., Inc.","cite":"423 F.3d 90","y":2005,"url":"https://www.courtlistener.com/c/F.3d/423/90/","op":3,"by":{"0":"37, 38, 39"}},{"t":"case","label":"Control Data Corp. v. S.C.S.C. Corp.","cite":"53 F.3d 930","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/53/930/","by":{"0":"6"}},{"t":"case","label":"Cooper Indus. Inc. v. Aviall Servs., Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"op":5,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Correctional Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"E.I. du Pont de Nemours & Co. v. United States","cite":"460 F.3d 515","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/460/515/","op":2,"by":{"0":"40, 41, 42, 45"}},{"t":"case","label":"E.I. du Pont de Nemours & Co. v. United States","cite":"365 F.3d 1367","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/365/1367/","by":{"0":"45"}},{"t":"case","label":"Elementis Chromium L.P. v. Coastal States Petroleum Co.","cite":"450 F.3d 607","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/450/607/","by":{"0":"38"}},{"t":"case","label":"F. Hoffmann-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"sum":"After respondent Mans filed for relief under Chapter 11 of the Bankruptcy Code, petitioners William and Norinne Field alleged, in effect, that letters Mans had written to them constituted fraudulent representations on which they relied in continuing to extend credit to a corporation controlled by Mans, and that, accordingly, Mans's obligation to them as guarantor of the corporation's debt should be excepted from …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Franchise Tax Bd. v. Construction Laborers Vacation Trust","cite":"463 U.S. 1","y":1983,"id":"1982/82-695","sc":1,"sum":"The case is not within the removal jurisdiction conferred by 28 U. S. C. § 1441.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"sum":"In a 5-to-4 decision written by Justice Ruth Bader Ginsburg, the Court held that the intention of the Tax Injunction Act (TIA) was to prevent taxpayers from trying to avoid their state taxes through federal litigation. TIA was not intended, however, to prevent all federal interference with state taxation.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"op":3,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Key Tronic Corp. v. United States","cite":"511 U.S. 809","y":1994,"id":"1993/93-376","sc":1,"op":3,"ar":2,"sum":"Stating in dictum that § 107 “impliedly authorizes private parties to recover cleanup costs from other PRP[s]” (empha­ sis added).","sumSrc":"opinion","by":{"0":"3, 16, 18, 46"}},{"t":"case","label":"Metropolitan Water Reclamation Dist. v. North Am. Galvanizing & Coatings, Inc.","cite":"473 F.3d 824","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/473/824/","op":2,"by":{"0":"19"}},{"t":"case","label":"Meghrig v. KFC Western, Inc.","cite":"516 U.S. 479","y":1996,"id":"1995/95-83","sc":1,"sum":"In a unanimous opinion delivered by Justice Sandra Day O'Connor the Court held that section 6972 does not authorize a private cause of action to recover the prior cost of cleaning up toxic waste that does not, at the time of suit, continue to pose an endangerment to health or the environment.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Navarijo-Barrios v. Ashcroft","cite":"322 F.3d 561","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/322/561/","sum":"Stating that “[i]t is well settled that we do not consider arguments raised for the first time in a reply brief”.","sumSrc":"brief:0","by":{"0":"47"}},{"t":"case","label":"New Castle County v. Halliburton NUS Corp.","cite":"111 F.3d 1116","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/111/1116/","sum":"Stating that “a section 107 action brought for recovery of costs may be brought only by innocent parties that have undertaken clean-ups”.","sumSrc":"brief:0","by":{"0":"4, 6, 16, 30, 34, 38"}},{"t":"case","label":"Northwest Airlines, Inc. v. Transport Workers Union","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"op":1,"ar":1,"sum":"Petitioner has neither a federal statutory nor a federal common-law right to contribution from respondent unions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22, 24"}},{"t":"case","label":"Pennsylvania v. Union Gas Co.","cite":"491 U.S. 1","y":1989,"id":"1988/87-1241","sc":1,"sum":"The judgment is affirmed, and the case is remanded. 832 F. 2d 1343, affirmed and remanded. JUSTICE BRENNAN delivered the opinion of the Court with respect to Parts I and II, concluding that CERCLA, as amended by SARA, clearly expresses an intent to hold States liable in damages in federal court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 17"}},{"t":"case","label":"Pinal Creek Group v. Newmont Mining Corp.","cite":"118 F.3d 1298","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/118/1298/","op":1,"sum":"Noting that such a regime “would immunize the claimant-PRP from the risk of orphan-share liability and would restrict substantially the ability of courts to apportion costs equitably pursuant to § 113(f)”.","sumSrc":"brief:0","by":{"0":"6, 31, 32, 35, 38"}},{"t":"case","label":"Pinole Point Props., Inc. v. Bethlemen Steel Corp.","cite":"596 F. Supp. 283","y":1984,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./596/283/","by":{"0":"28"}},{"t":"case","label":"Pneumo Abex Corp. v. High Point, Thomasville & Denton R.R.","cite":"142 F.3d 769","y":1998,"url":"https://www.courtlistener.com/c/F.3d/142/769/","by":{"0":"6"}},{"t":"case","label":"Porto Rico Ry., Light & Power Co. v. Mor","cite":"253 U.S. 345","y":1920,"id":"scdb/1919-067","sc":1,"sum":"In the provision of the Act of March 2, 1917, c. 145, 39 Stat. 965, which gives the United States District Court for Porto Rico jurisdiction “where all the parties on either side of the controversy are citizens or subjects of a foreign State or States, or citizens of a State, Territory, or District of the United States not domiciled in Porto Rico,” etc., the clause “not domiciled in Porto Rico” relates to both …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Redwing Carriers, Inc. v. Saraland Apartments","cite":"94 F.3d 1489","y":1996,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/94/1489/","by":{"0":"6, 34"}},{"t":"case","label":"Schweiker v. Chilicky","cite":"487 U.S. 412","y":1988,"id":"1987/86-1781","sc":1,"sum":"The Court held that when a government employee violates a citizen’s legal rights, that citizen is not allowed to pursue monetary damages as compensation when the violated statute does not contain monetary damages as a possible remedy.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Skelly Oil Co. v. Phillips Petroleum Co.","cite":"339 U.S. 667","y":1950,"id":"scdb/1949-088","sc":1,"sum":"Respondent oil company had contracts with three producers to purchase gas for resale to a pipeline company which had applied to the Federal Power Commission for a certificate of public convenience and necessity under the Natural Gas Act. Each contract provided for termination by the producer upon notice to the respondent at any time after December 1, 1946, \"but before the issuance of such certificate.\" On November …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Texas Industries, Inc. v. Radcliff Materials, Inc.","cite":"451 U.S. 630","y":1981,"id":"1980/79-1144","sc":1,"op":1,"ar":1,"sum":"There is no basis in federal statutory or common law for allowing federal courts to fashion the right to contribution urged by petitioner.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Town of New Windsor v. Tesa Tuck, Inc.","cite":"919 F. Supp. 662","y":1996,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./919/662/","sum":"Explaining that such a regime would lead to “sequential, piecemeal litigation”.","sumSrc":"brief:0","by":{"0":"38"}},{"t":"case","label":"United States v. A.S. Kreider Co.","cite":"313 U.S. 443","y":1941,"id":"scdb/1940-133","sc":1,"sum":"1. Section 24 (20) of the Judicial Code, which gives the District Courts jurisdiction concurrent with the Court of Claims over certain suits against the United States, provides that no suit shall be allowed thereunder unless the same shall have been brought within six years after the right accrued for which the claim is made. Held, that the six-years period is an outside limit consistent with the five-years limit on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3, 4"}},{"t":"case","label":"United States v. Colorado & E. R.R.","cite":"50 F.3d 1530","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/50/1530/","sum":"Noting that, “were PRPs * * * allowed to recover expenditures incurred in cleanup and remediation from other PRPs under § 107’s strict liability scheme, § 113(f) would be rendered meaningless”.","sumSrc":"brief:0","by":{"0":"6, 30, 31, 38"}},{"t":"case","label":"United States v. E.I. du Pont de Nemours & Co.","cite":"432 F.3d 161","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/432/161/","by":{"0":"20"}},{"t":"case","label":"United States v. Estate of Romani","cite":"523 U.S. 517","y":1998,"id":"1997/96-1613","sc":1,"sum":"The Court held that section 3713(a) does not require that a federal tax claim be given preference over a judgment creditor's perfected lien on real property.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"United States v. Hooker Chems. & Plastics Corp.","cite":"850 F. Supp. 993","y":1994,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./850/993/","by":{"0":"44"}},{"t":"case","label":"United States v. New Castle County","cite":"642 F. Supp. 1258","y":1986,"court":"D. Del.","url":"https://www.courtlistener.com/c/F.%20Supp./642/1258/","sum":"Holding that PRP had right to contribution under federal common law.","sumSrc":"brief:0","by":{"0":"5, 27"}},{"t":"case","label":"United States v. Nordic Village, Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"United States v. Shell Oil Co.","cite":"294 F.3d 1045","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/294/1045/","by":{"0":"44"}},{"t":"case","label":"United States v. Vertac Chem. Corp.","cite":"46 F.3d 803","y":1995,"url":"https://www.courtlistener.com/c/F.3d/46/803/","by":{"0":"44"}},{"t":"case","label":"United States v. Westinghouse Elec. Corp.","cite":"1983 WL 160587","y":1983,"court":"S.D. Ind. June 29","sum":"Holding that PRP had no right to contribution.","sumSrc":"brief:0","by":{"0":"5, 27"}},{"t":"case","label":"United Technologies Corp. v. Browning-Ferris Indus.","cite":"33 F.3d 96","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/33/96/","op":1,"sum":"Noting that “it is sensible to assume that Congress intended only innocent parties—not parties who were themselves liable—to be permitted to recoup the whole of their expenditures”.","sumSrc":"brief:0","by":{"0":"6, 16, 23, 30, 31, 34"}},{"t":"case","label":"Walls v. Waste Res. Corp.","cite":"761 F.2d 311","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/761/311/","by":{"0":"29"}},{"t":"case","label":"Wickland Oil Terminals v. Asarco, Inc.","cite":"792 F.2d 887","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/792/887/","by":{"0":"20, 29"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(9)","(14)","(20)","(21)","(26)","(29)","(40)"],"stext":{"head":"§9601. Definitions","paras":[[0,"For purpose of this subchapter—"],[1,"(1) The term \"act of God\" means an unanticipated grave natural disaster or other natural phenomenon of an exceptional, inevitable, and irresistible character, the effects of which could not have been prevented or avoided by the exercise of due care or foresight."],[1,"(2) The term \"Administrator\" means the Administrator of the United States Environmental Protection Agency."],[1,"(3) The term \"barrel\" means forty-two United States gallons at sixty degrees Fahrenheit."],[1,"(4) The term \"claim\" means a demand in writing for a sum certain."],[1,"(5) The term \"claimant\" means any person who presents a claim for compensation under this chapter."],[1,"(6) The term \"damages\" means damages for injury or loss of natural resources as set forth in section 9607(a) or 9611(b) of this title."],[1,"(7) The term \"drinking water supply\" means any raw or finished water source that is or may be used by a public water system (as defined in the Safe Drinking Water Act [42 U.S.C. 300f et seq.]) or as drinking water by one or more individuals."],[1,"(8) The term \"environment\" means (A) the navigable waters, the waters of the contiguous zone, and the ocean waters of which the natural resources are under the exclusive management authority of the United States under the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.], and (B) any other surface water, ground water, drinking water supply, land surface or subsurface strata, or ambient air within the United States or under the jurisdiction of the United States."],[1,"(9) The term \"facility\" means (A) any building, structure, installation, equipment, pipe or pipeline (including any pipe into a sewer or publicly owned treatment works), well, pit, pond, lagoon, impoundment, ditch, landfill, storage container, motor vehicle, rolling stock, or aircraft, or (B) any site or area where a hazardous substance has been deposited, stored, disposed of, or placed, or otherwise come to be located; but does not include any consumer product in consumer use or any vessel."],[1,"(10) The term \"federally permitted release\" means (A) discharges in compliance with a permit under section 402 of the Federal Water Pollution Control Act [33 U.S.C. 1342], (B) discharges resulting from circumstances identified and reviewed and made part of the public record with respect to a permit issued or modified under section 402 of the Federal Water Pollution Control Act and subject to a condition of such permit, (C) continuous or anticipated intermittent discharges from a point source, identified in a permit or permit application under section 402 of the Federal Water Pollution Control Act, which are caused by events occurring within the scope of relevant operating or treatment systems, (D) discharges in compliance with a legally enforceable permit under section 404 of the Federal Water Pollution Control Act [33 U.S.C. 1344], (E) releases in compliance with a legally enforceable final permit issued pursuant to section 3005(a) through (d) of the Solid Waste Disposal Act [42 U.S.C. 6925(a)–(d)] from a hazardous waste treatment, storage, or disposal facility when such permit specifically identifies the hazardous substances and makes such substances subject to a standard of practice, control procedure or bioassay limitation or condition, or other control on the hazardous substances in such releases, (F) any release in compliance with a legally enforceable permit issued under section 1412 of title 33 of 1 section 1413 of title 33, (G) any injection of fluids authorized under Federal underground injection control programs or State programs submitted for Federal approval (and not disapproved by the Administrator of the Environmental Protection Agency) pursuant to part C of the Safe Drinking Water Act [42 U.S.C. 300h et seq.], (H) any emission into the air subject to a permit or control regulation under section 111 [42 U.S.C. 7411], section 112 [42 U.S.C. 7412], title I part C [42 U.S.C. 7470 et seq.], title I part D [42 U.S.C. 7501 et seq.], or State implementation plans submitted in accordance with section 110 of the Clean Air Act [42 U.S.C. 7410] (and not disapproved by the Administrator of the Environmental Protection Agency), including any schedule or waiver granted, promulgated, or approved under these sections, (I) any injection of fluids or other materials authorized under applicable State law (i) for the purpose of stimulating or treating wells for the production of crude oil, natural gas, or water, (ii) for the purpose of secondary, tertiary, or other enhanced recovery of crude oil or natural gas, or (iii) which are brought to the surface in conjunction with the production of crude oil or natural gas and which are reinjected, (J) the introduction of any pollutant into a publicly owned treatment works when such pollutant is specified in and in compliance with applicable pretreatment standards of section 307(b) or (c) of the Clean Water Act [33 U.S.C. 1317(b), (c)] and enforceable requirements in a pretreatment program submitted by a State or municipality for Federal approval under section 402 of such Act [33 U.S.C. 1342], and (K) any release of source, special nuclear, or byproduct material, as those terms are defined in the Atomic Energy Act of 1954 [42 U.S.C. 2011 et seq.], in compliance with a legally enforceable license, permit, regulation, or order issued pursuant to the Atomic Energy Act of 1954."],[1,"(11) The term \"Fund\" or \"Trust Fund\" means the Hazardous Substance Superfund established by section 9507 of title 26."],[1,"(12) The term \"ground water\" means water in a saturated zone or stratum beneath the surface of land or water."],[1,"(13) The term \"guarantor\" means any person, other than the owner or operator, who provides evidence of financial responsibility for an owner or operator under this chapter."],[1,"(14) The term \"hazardous substance\" means (A) any substance designated pursuant to section 311(b)(2)(A) of the Federal Water Pollution Control Act [33 U.S.C. 1321(b)(2)(A)], (B) any element, compound, mixture, solution, or substance designated pursuant to section 9602 of this title, (C) any hazardous waste having the characteristics identified under or listed pursuant to section 3001 of the Solid Waste Disposal Act [42 U.S.C. 6921] (but not including any waste the regulation of which under the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.] has been suspended by Act of Congress), (D) any toxic pollutant listed under section 307(a) of the Federal Water Pollution Control Act [33 U.S.C. 1317(a)], (E) any hazardous air pollutant listed under section 112 of the Clean Air Act [42 U.S.C. 7412], and (F) any imminently hazardous chemical substance or mixture with respect to which the Administrator has taken action pursuant to section 7 of the Toxic Substances Control Act [15 U.S.C. 2606]. The term does not include petroleum, including crude oil or any fraction thereof which is not otherwise specifically listed or designated as a hazardous substance under subparagraphs (A) through (F) of this paragraph, and the term does not include natural gas, natural gas liquids, liquefied natural gas, or synthetic gas usable for fuel (or mixtures of natural gas and such synthetic gas)."],[1,"(15) The term \"navigable waters\" or \"navigable waters of the United States\" means the waters of the United States, including the territorial seas."],[1,"(16) The term \"natural resources\" means land, fish, wildlife, biota, air, water, ground water, drinking water supplies, and other such resources belonging to, managed by, held in trust by, appertaining to, or otherwise controlled by the United States (including the resources of the fishery conservation zone established by the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.]), any State or local government, any foreign government, any Indian tribe, or, if such resources are subject to a trust restriction on alienation, any member of an Indian tribe."],[1,"(17) The term \"offshore facility\" means any facility of any kind located in, on, or under, any of the navigable waters of the United States, and any facility of any kind which is subject to the jurisdiction of the United States and is located in, on, or under any other waters, other than a vessel or a public vessel."],[1,"(18) The term \"onshore facility\" means any facility (including, but not limited to, motor vehicles and rolling stock) of any kind located in, on, or under, any land or nonnavigable waters within the United States."],[1,"(19) The term \"otherwise subject to the jurisdiction of the United States\" means subject to the jurisdiction of the United States by virtue of United States citizenship, United States vessel documentation or numbering, or as provided by international agreement to which the United States is a party."],[1,"(20)(A) The term \"owner or operator\" means (i) in the case of a vessel, any person owning, operating, or chartering by demise, such vessel, (ii) in the case of an onshore facility or an offshore facility, any person owning or operating such facility, and (iii) in the case of any facility, title or control of which was conveyed due to bankruptcy, foreclosure, tax delinquency, abandonment, or similar means to a unit of State or local government, any person who owned, operated, or otherwise controlled activities at such facility immediately beforehand. Such term does not include a person, who, without participating in the management of a vessel or facility, holds indicia of ownership primarily to protect his security interest in the vessel or facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9601?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9601. Definitions","tname":"The Public Health and Welfare","by":{"0":"2, 4, 4, 4, 4, 15, 4, 4, 16"}},{"t":"usc","label":"42 U.S.C. § 9604","url":"https://www.law.cornell.edu/uscode/text/42/9604","subs":["(k)"],"by":{"0":"3, 7"}},{"t":"usc","label":"42 U.S.C. § 9605","url":"https://www.law.cornell.edu/uscode/text/42/9605","by":{"0":"4"}},{"t":"usc","label":"42 U.S.C. § 9606","url":"https://www.law.cornell.edu/uscode/text/42/9606","by":{"0":"7"}},{"t":"usc","label":"42 U.S.C. § 9607","url":"https://www.law.cornell.edu/uscode/text/42/9607","subs":["(a)","(a)(1)","(o)","(r)(1)"],"stext":{"head":"§9607. Liability","paras":[[0,"(a) Covered persons; scope; recoverable costs and damages; interest rate; \"comparable maturity\" date"],[0,"Notwithstanding any other provision or rule of law, and subject only to the defenses set forth in subsection (b) of this section—"],[1,"(1) the owner and operator of a vessel or a facility,"],[1,"(2) any person who at the time of disposal of any hazardous substance owned or operated any facility at which such hazardous substances were disposed of,"],[1,"(3) any person who by contract, agreement, or otherwise arranged for disposal or treatment, or arranged with a transporter for transport for disposal or treatment, of hazardous substances owned or possessed by such person, by any other party or entity, at any facility or incineration vessel owned or operated by another party or entity and containing such hazardous substances, and"],[1,"(4) any person who accepts or accepted any hazardous substances for transport to disposal or treatment facilities, incineration vessels or sites selected by such person, from which there is a release, or a threatened release which causes the incurrence of response costs, of a hazardous substance, shall be liable for—"],[2,"(A) all costs of removal or remedial action incurred by the United States Government or a State or an Indian tribe not inconsistent with the national contingency plan;"],[2,"(B) any other necessary costs of response incurred by any other person consistent with the national contingency plan;"],[2,"(C) damages for injury to, destruction of, or loss of natural resources, including the reasonable costs of assessing such injury, destruction, or loss resulting from such a release; and"],[2,"(D) the costs of any health assessment or health effects study carried out under section 9604(i) of this title."],[0,"The amounts recoverable in an action under this section shall include interest on the amounts recoverable under subparagraphs (A) through (D). Such interest shall accrue from the later of (i) the date payment of a specified amount is demanded in writing, or (ii) the date of the expenditure concerned. The rate of interest on the outstanding unpaid balance of the amounts recoverable under this section shall be the same rate as is specified for interest on investments of the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26. For purposes of applying such amendments to interest under this subsection, the term \"comparable maturity\" shall be determined with reference to the date on which interest accruing under this subsection commences."],[0,"(b) Defenses"],[0,"There shall be no liability under subsection (a) of this section for a person otherwise liable who can establish by a preponderance of the evidence that the release or threat of release of a hazardous substance and the damages resulting therefrom were caused solely by—"],[1,"(1) an act of God;"],[1,"(2) an act of war;"],[1,"(3) an act or omission of a third party other than an employee or agent of the defendant, or than one whose act or omission occurs in connection with a contractual relationship, existing directly or indirectly, with the defendant (except where the sole contractual arrangement arises from a published tariff and acceptance for carriage by a common carrier by rail), if the defendant establishes by a preponderance of the evidence that (a) he exercised due care with respect to the hazardous substance concerned, taking into consideration the characteristics of such hazardous substance, in light of all relevant facts and circumstances, and (b) he took precautions against foreseeable acts or omissions of any such third party and the consequences that could foreseeably result from such acts or omissions; or"],[1,"(4) any combination of the foregoing paragraphs."],[0,"(c) Determination of amounts"],[0,"(1) Except as provided in paragraph (2) of this subsection, the liability under this section of an owner or operator or other responsible person for each release of a hazardous substance or incident involving release of a hazardous substance shall not exceed—"],[1,"(A) for any vessel, other than an incineration vessel, which carries any hazardous substance as cargo or residue, $300 per gross ton, or $5,000,000, whichever is greater;"],[1,"(B) for any other vessel, other than an incineration vessel, $300 per gross ton, or $500,000, whichever is greater;"],[1,"(C) for any motor vehicle, aircraft, hazardous liquid pipeline facility (as defined in section 60101(a) of title 49), or rolling stock, $50,000,000 or such lesser amount as the President shall establish by regulation, but in no event less than $5,000,000 (or, for releases of hazardous substances as defined in section 9601(14)(A) of this title into the navigable waters, $8,000,000). Such regulations shall take into account the size, type, location, storage, and handling capacity and other matters relating to the likelihood of release in each such class and to the economic impact of such limits on each such class; or"],[1,"(D) for any incineration vessel or any facility other than those specified in subparagraph (C) of this paragraph, the total of all costs of response plus $50,000,000 for any damages under this subchapter."],[0,"(2) Notwithstanding the limitations in paragraph (1) of this subsection, the liability of an owner or operator or other responsible person under this section shall be the full and total costs of response and damages, if (A)(i) the release or threat of release of a hazardous substance was the result of willful misconduct or willful negligence within the privity or knowledge of such person, or (ii) the primary cause of the release was a violation (within the privity or knowledge of such person) of applicable safety, construction, or operating standards or regulations; or (B) such person fails or refuses to provide all reasonable cooperation and assistance requested by a responsible public official in connection with response activities under the national contingency plan with respect to regulated carriers subject to the provisions of title 49 or vessels subject to the provisions of title 33 or 46, subparagraph (A)(ii) of this paragraph shall be deemed to refer to Federal standards or regulations."],[0,"(3) If any person who is liable for a release or threat of release of a hazardous substance fails without sufficient cause to properly provide removal or remedial action upon order of the President pursuant to section 9604 or 9606 of this title, such person may be liable to the United States for punitive damages in an amount at least equal to, and not more than three times, the amount of any costs incurred by the Fund as a result of such failure to take proper action. The President is authorized to commence a civil action against any such person to recover the punitive damages, which shall be in addition to any costs recovered from such person pursuant to section 9612(c) of this title. Any moneys received by the United States pursuant to this subsection shall be deposited in the Fund."],[0,"(d) Rendering care or advice"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), no person shall be liable under this subchapter for costs or damages as a result of actions taken or omitted in the course of rendering care, assistance, or advice in accordance with the National Contingency Plan (\"NCP\") or at the direction of an onscene coordinator appointed under such plan, with respect to an incident creating a danger to public health or welfare or the environment as a result of any releases of a hazardous substance or the threat thereof. This paragraph shall not preclude liability for costs or damages as the result of negligence on the part of such person."],[0,"(2) State and local governments"],[1,"No State or local government shall be liable under this subchapter for costs or damages as a result of actions taken in response to an emergency created by the release or threatened release of a hazardous substance generated by or from a facility owned by another person. This paragraph shall not preclude liability for costs or damages as a result of gross negligence or intentional misconduct by the State or local government. For the purpose of the preceding sentence, reckless, willful, or wanton misconduct shall constitute gross negligence."],[0,"(3) Savings provision"],[1,"This subsection shall not alter the liability of any person covered by the provisions of paragraph (1), (2), (3), or (4) of subsection (a) of this section with respect to the release or threatened release concerned."],[0,"(e) Indemnification, hold harmless, etc., agreements or conveyances; subrogation rights"],[0,"(1) No indemnification, hold harmless, or similar agreement or conveyance shall be effective to transfer from the owner or operator of any vessel or facility or from any person who may be liable for a release or threat of release under this section, to any other person the liability imposed under this section. Nothing in this subsection shall bar any agreement to insure, hold harmless, or indemnify a party to such agreement for any liability under this section."],[0,"(2) Nothing in this subchapter, including the provisions of paragraph (1) of this subsection, shall bar a cause of action that an owner or operator or any other person subject to liability under this section, or a guarantor, has or would have, by reason of subrogation or otherwise against any person."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9607?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§9607. Liability","tname":"The Public Health and Welfare","by":{"0":"7, 7, 7, 7, 7, 7, 45"}},{"t":"usc","label":"42 U.S.C. § 9613","url":"https://www.law.cornell.edu/uscode/text/42/9613","subs":["(f)","(f)(1)","(f)(2)","(f)(3)(B)","(g)(2)","(g)(3)"],"stext":{"head":"§9613. Civil proceedings","paras":[[0,"(a) Review of regulations in Circuit Court of Appeals of the United States for the District of Columbia"],[0,"Review of any regulation promulgated under this chapter may be had upon application by any interested person only in the Circuit Court of Appeals of the United States for the District of Columbia. Any such application shall be made within ninety days from the date of promulgation of such regulations. Any matter with respect to which review could have been obtained under this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement or to obtain damages or recovery of response costs."],[0,"(b) Jurisdiction; venue"],[0,"Except as provided in subsections (a) and (h) of this section, the United States district courts shall have exclusive original jurisdiction over all controversies arising under this chapter, without regard to the citizenship of the parties or the amount in controversy. Venue shall lie in any district in which the release or damages occurred, or in which the defendant resides, may be found, or has his principal office. For the purposes of this section, the Fund shall reside in the District of Columbia."],[0,"(c) Controversies or other matters resulting from tax collection or tax regulation review"],[0,"The provisions of subsections (a) and (b) of this section shall not apply to any controversy or other matter resulting from the assessment of collection of any tax, as provided by subchapter II 1 of this chapter, or to the review of any regulation promulgated under title 26."],[0,"(d) Litigation commenced prior to December 11, 1980"],[0,"No provision of this chapter shall be deemed or held to moot any litigation concerning any release of any hazardous substance, or any damages associated therewith, commenced prior to December 11, 1980."],[0,"(e) Nationwide service of process"],[0,"In any action by the United States under this chapter, process may be served in any district where the defendant is found, resides, transacts business, or has appointed an agent for the service of process."],[0,"(f) Contribution"],[0,"(1) Contribution"],[1,"Any person may seek contribution from any other person who is liable or potentially liable under section 9607(a) of this title, during or following any civil action under section 9606 of this title or under section 9607(a) of this title. Such claims shall be brought in accordance with this section and the Federal Rules of Civil Procedure, and shall be governed by Federal law. In resolving contribution claims, the court may allocate response costs among liable parties using such equitable factors as the court determines are appropriate. Nothing in this subsection shall diminish the right of any person to bring an action for contribution in the absence of a civil action under section 9606 of this title or section 9607 of this title."],[0,"(2) Settlement"],[1,"A person who has resolved its liability to the United States or a State in an administrative or judicially approved settlement shall not be liable for claims for contribution regarding matters addressed in the settlement. Such settlement does not discharge any of the other potentially liable persons unless its terms so provide, but it reduces the potential liability of the others by the amount of the settlement."],[0,"(3) Persons not party to settlement"],[1,"(A) If the United States or a State has obtained less than complete relief from a person who has resolved its liability to the United States or the State in an administrative or judicially approved settlement, the United States or the State may bring an action against any person who has not so resolved its liability."],[1,"(B) A person who has resolved its liability to the United States or a State for some or all of a response action or for some or all of the costs of such action in an administrative or judicially approved settlement may seek contribution from any person who is not party to a settlement referred to in paragraph (2)."],[1,"(C) In any action under this paragraph, the rights of any person who has resolved its liability to the United States or a State shall be subordinate to the rights of the United States or the State. Any contribution action brought under this paragraph shall be governed by Federal law."],[0,"(g) Period in which action may be brought"],[0,"(1) Actions for natural resource damages"],[1,"Except as provided in paragraphs (3) and (4), no action may be commenced for damages (as defined in section 9601(6) of this title) under this chapter, unless that action is commenced within 3 years after the later of the following:"],[2,"(A) The date of the discovery of the loss and its connection with the release in question."],[2,"(B) The date on which regulations are promulgated under section 9651(c) of this title."],[1,"With respect to any facility listed on the National Priorities List (NPL), any Federal facility identified under section 9620 of this title (relating to Federal facilities), or any vessel or facility at which a remedial action under this chapter is otherwise scheduled, an action for damages under this chapter must be commenced within 3 years after the completion of the remedial action (excluding operation and maintenance activities) in lieu of the dates referred to in subparagraph (A) or (B). In no event may an action for damages under this chapter with respect to such a vessel or facility be commenced (i) prior to 60 days after the Federal or State natural resource trustee provides to the President and the potentially responsible party a notice of intent to file suit, or (ii) before selection of the remedial action if the President is diligently proceeding with a remedial investigation and feasibility study under section 9604(b) of this title or section 9620 of this title (relating to Federal facilities). The limitation in the preceding sentence on commencing an action before giving notice or before selection of the remedial action does not apply to actions filed on or before October 17, 1986."],[0,"(2) Actions for recovery of costs"],[1,"An initial action for recovery of the costs referred to in section 9607 of this title must be commenced—"],[2,"(A) for a removal action, within 3 years after completion of the removal action, except that such cost recovery action must be brought within 6 years after a determination to grant a waiver under section 9604(c)(1)(C) of this title for continued response action; and"],[2,"(B) for a remedial action, within 6 years after initiation of physical on-site construction of the remedial action, except that, if the remedial action is initiated within 3 years after the completion of the removal action, costs incurred in the removal action may be recovered in the cost recovery action brought under this subparagraph."],[1,"In any such action described in this subsection, the court shall enter a declaratory judgment on liability for response costs or damages that will be binding on any subsequent action or actions to recover further response costs or damages. A subsequent action or actions under section 9607 of this title for further response costs at the vessel or facility may be maintained at any time during the response action, but must be commenced no later than 3 years after the date of completion of all response action. Except as otherwise provided in this paragraph, an action may be commenced under section 9607 of this title for recovery of costs at any time after such costs have been incurred."],[0,"(3) Contribution"],[1,"No action for contribution for any response costs or damages may be commenced more than 3 years after—"],[2,"(A) the date of judgment in any action under this chapter for recovery of such costs or damages, or"],[2,"(B) the date of an administrative order under section 9622(g) of this title (relating to de minimis settlements) or 9622(h) of this title (relating to cost recovery settlements) or entry of a judicially approved settlement with respect to such costs or damages."],[0,"(4) Subrogation"],[1,"No action based on rights subrogated pursuant to this section by reason of payment of a claim may be commenced under this subchapter more than 3 years after the date of payment of such claim."],[0,"(5) Actions to recover indemnification payments"],[1,"Notwithstanding any other provision of this subsection, where a payment pursuant to an indemnification agreement with a response action contractor is made under section 9619 of this title, an action under section 9607 of this title for recovery of such indemnification payment from a potentially responsible party may be brought at any time before the expiration of 3 years from the date on which such payment is made."],[0,"(6) Minors and incompetents"],[1,"The time limitations contained herein shall not begin to run—"],[2,"(A) against a minor until the earlier of the date when such minor reaches 18 years of age or the date on which a legal representative is duly appointed for such minor, or"],[2,"(B) against an incompetent person until the earlier of the date on which such incompetent's incompetency ends or the date on which a legal representative is duly appointed for such incompetent."],[0,"(h) Timing of review"],[0,"No Federal court shall have jurisdiction under Federal law other than under section 1332 of title 28 (relating to diversity of citizenship jurisdiction) or under State law which is applicable or relevant and appropriate under section 9621 of this title (relating to cleanup standards) to review any challenges to removal or remedial action selected under section 9604 of this title, or to review any order issued under section 9606(a) of this title, in any action except one of the following:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9613?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§9613. Civil proceedings","tname":"The Public Health and Welfare","by":{"0":"45, 45, 45, 45, 45, 45, 45"}},{"t":"usc","label":"42 U.S.C. § 9620","url":"https://www.law.cornell.edu/uscode/text/42/9620","subs":["(a)(1)"],"by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 9622","url":"https://www.law.cornell.edu/uscode/text/42/9622","subs":["(a)","(d)","(g)","(h)"],"by":{"0":"3, 41, 3, 3, 3"}},{"t":"usc","label":"42 U.S.C. § 9628","url":"https://www.law.cornell.edu/uscode/text/42/9628","subs":["(a)","(b)(1)(A)(ii)"],"by":{"0":"7, 7"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","by":{"0":"43"}},{"t":"usc","label":"42 U.S.C. § 6924","url":"https://www.law.cornell.edu/uscode/text/42/6924","subs":["(u)"],"by":{"0":"43"}},{"t":"usc","label":"42 U.S.C. § 6925","url":"https://www.law.cornell.edu/uscode/text/42/6925","subs":["(a)"],"by":{"0":"43"}},{"t":"law","label":"Small Business Liability Relief and Brownfields Revitalization Act, Pub. L. No. 107-118","url":"https://www.govinfo.gov/link/plaw/107/public/118","by":{"0":"7"}},{"t":"law","label":"Pub. L. No. 99-499","url":"https://www.govinfo.gov/link/statute/100/1613","by":{"0":"2"}},{"t":"usc","label":"10 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/10/2701","by":{"0":"44"}},{"t":"reg","label":"3 C.F.R. pt. 193","url":"https://www.ecfr.gov/current/title-3/part-193","by":{"0":"3"}},{"t":"reg","label":"40 C.F.R. pt. 300","url":"https://www.ecfr.gov/current/title-40/part-300","by":{"0":"4"}},{"t":"reg","label":"48 Fed. Reg. 40,661","url":"https://www.govinfo.gov/link/fr/48/40661","by":{"0":"40"}},{"t":"reg","label":"61 Fed. Reg. 54,215","url":"https://www.govinfo.gov/link/fr/61/54215","by":{"0":"44"}},{"t":"reg","label":"65 Fed. Reg. 32,123","url":"https://www.govinfo.gov/link/fr/65/32123","by":{"0":"44"}},{"t":"reg","label":"67 Fed. Reg. 8557","url":"https://www.govinfo.gov/link/fr/67/8557","by":{"0":"44"}}]};